<script setup lang="ts">
import {computed} from 'vue'
import type {Row} from '../types'
import {metricLabel} from '../format'
import UiIcon from '../components/UiIcon.vue'
import StatusBadge from '../components/StatusBadge.vue'

const props=defineProps<{view:'batches'|'review',batches:Row[],tasks:Row[],selectedBatch:string,nextBatch:string,nextTask:string,loading:boolean,busy:boolean}>()
const emit=defineEmits<{selectBatch:[id:string],moreBatches:[],moreTasks:[],inspect:[id:string],download:[]}>()
const visibleTasks=computed(()=>props.view==='review'?props.tasks.filter(t=>t.status==='COMPLETED'&&t.review_status==='PENDING'):props.tasks)
const chosenBatch=computed(()=>props.batches.find(batch=>batch.id===props.selectedBatch))
const currentTitle=computed(()=>props.view==='review'?'等待人工复核':props.selectedBatch?(chosenBatch.value?.title||'所选研究批次'):'全部核验任务')
function date(value:string){const parsed=new Date(value);return Number.isNaN(parsed.getTime())?'日期未知':parsed.toLocaleDateString('zh-CN',{month:'2-digit',day:'2-digit'})}
function selectFromEvent(event:Event){emit('selectBatch',(event.target as HTMLSelectElement).value)}
</script>

<template>
  <div :class="['task-workspace',{'review-workspace':view==='review'}]">
    <aside v-if="view==='batches'" class="batch-list" aria-labelledby="batch-list-heading">
      <div class="batch-list-heading"><h2 id="batch-list-heading">研究批次</h2><span class="loaded-count">已加载 {{batches.length}}</span></div>
      <button :class="['all-batches',{chosen:!selectedBatch}]" @click="emit('selectBatch','')" :disabled="busy"><UiIcon name="layers" :size="16"/><span>全部任务</span></button>
      <div class="batch-items"><button v-for="batch in batches" :key="batch.id" :class="['batch-card',{chosen:selectedBatch===batch.id}]" :aria-pressed="selectedBatch===batch.id" :title="batch.title" :disabled="busy" @click="emit('selectBatch',batch.id)"><span class="batch-meta"><span class="batch-id">{{batch.id.slice(0,8)}}</span><time :datetime="batch.created_at">{{date(batch.created_at)}}</time></span><h3>{{batch.title}}</h3><span class="batch-bottom"><span>{{batch.item_count}} 项任务</span></span></button></div>
      <p v-if="!batches.length&&!loading" class="batch-empty">还没有研究批次。<br>新建批次后，在这里跟踪核验进度。</p>
      <button v-if="nextBatch" class="batch-more" @click="emit('moreBatches')" :disabled="busy||loading">{{loading?'正在加载…':'加载更多批次'}}<UiIcon name="chevron-down" :size="14"/></button>
    </aside>
    <section class="tasks-panel" aria-labelledby="task-panel-title" :aria-busy="loading">
      <div v-if="view==='batches'" class="compact-batches"><label for="batch-picker">研究批次 <span>已加载 {{batches.length}}</span></label><div class="compact-picker"><select id="batch-picker" :value="selectedBatch" @change="selectFromEvent" :disabled="busy"><option value="">全部任务</option><option v-for="batch in batches" :key="batch.id" :value="batch.id">{{batch.title}} · {{batch.id.slice(0,8)}}</option><option v-if="selectedBatch&&!chosenBatch" :value="selectedBatch">所选批次 · {{selectedBatch.slice(0,8)}}</option></select><button v-if="nextBatch" @click="emit('moreBatches')" :disabled="busy||loading">加载更多批次</button></div></div>
      <div class="tasks-heading"><div class="tasks-heading-copy"><h2 id="task-panel-title" :title="currentTitle">{{currentTitle}}</h2><p>{{view==='review'?'查看原始证据，独立记录你的复核决定。':'执行、机器核验与人工复核，各有明确记录。'}}</p></div><button v-if="view==='batches'&&selectedBatch" class="download-button" @click="emit('download')" :disabled="busy"><UiIcon name="download" :size="16"/><span>导出已审核结果</span></button></div>
      <div class="register-meta"><span><span class="register-dot" aria-hidden="true"></span>已加载 {{visibleTasks.length}} 项任务</span><span v-if="loading" role="status">正在更新…</span><span v-else class="register-help">{{view==='review'?'仅展示执行完成且待复核的任务':'执行完成不等于核验通过'}}</span></div>
      <div class="task-table-scroll"><table class="task-table" aria-label="核验任务"><thead><tr><th scope="col">公司 / 核验指标</th><th scope="col">执行状态</th><th scope="col">机器结论</th><th scope="col">人工复核</th><th scope="col" class="attempt-column">模型尝试</th><th scope="col"><span class="visually-hidden">操作</span></th></tr></thead><tbody><tr v-for="task in visibleTasks" :key="task.id"><td class="task-identity"><strong>{{task.ticker}}<span>FY{{task.fiscal_year}}</span></strong><span class="task-metric" :title="task.metric">{{metricLabel(task.metric)}}</span><span class="task-id">{{task.id.slice(0,8)}}</span></td><td><StatusBadge :value="task.status"/></td><td><StatusBadge :value="task.machine_verdict"/></td><td><StatusBadge :value="task.review_status"/></td><td class="attempt-column"><span class="attempt-count">{{task.dispatches}}</span><span class="attempt-unit"> 次</span></td><td class="task-action"><button @click="emit('inspect',task.id)" :disabled="busy">查看证据</button></td></tr></tbody></table></div>
      <div class="mobile-tasks"><article v-for="task in visibleTasks" :key="task.id" class="mobile-task"><div class="mobile-task-heading"><div><strong>{{task.ticker}} <span>FY{{task.fiscal_year}}</span></strong><p>{{metricLabel(task.metric)}}</p></div><button @click="emit('inspect',task.id)" :disabled="busy">查看证据</button></div><dl class="mobile-statuses"><div><dt>执行状态</dt><dd><StatusBadge :value="task.status"/></dd></div><div><dt>机器结论</dt><dd><StatusBadge :value="task.machine_verdict"/></dd></div><div><dt>人工复核</dt><dd><StatusBadge :value="task.review_status"/></dd></div></dl><p class="mobile-task-meta"><span>{{task.id.slice(0,8)}}</span><span>模型尝试 {{task.dispatches}} 次</span></p></article></div>
      <div v-if="!visibleTasks.length" class="tasks-empty" role="status"><div class="empty-icon"><UiIcon :name="view==='review'?'check-circle':'receipt'" :size="25"/></div><h3>{{loading?'正在读取任务…':view==='review'?'目前没有待复核任务':'这里还没有核验任务'}}</h3><p>{{loading?'任务状态与证据即将显示在这里。':view==='review'?'执行完成且等待审核的任务会出现在这里。':'选择一个研究批次，或新建批次开始核验。'}}</p></div>
      <div v-if="nextTask" class="task-pagination"><span>当前显示 {{visibleTasks.length}} 项，后续任务尚未加载</span><button @click="emit('moreTasks')" :disabled="busy||loading">{{loading?'正在加载…':'加载后续任务'}}<UiIcon name="chevron-down" :size="14"/></button></div>
    </section>
  </div>
</template>

