ow-wrap:anywhere}.task-id{display:block;margin-top:4px;color:var(--muted);font-size:12px}.attempt-count{font-size:14px;font-variant-numeric:tabular-nums}.attempt-unit{font-size:12px;color:var(--muted)}.task-action{text-align:right;white-space:nowrap}.task-action button,.mobile-task-heading button{display:inline-flex;align-items:center;gap:4px;border:0;padding:7px 0;font-size:14px;color:var(--primary);background:transparent;white-space:nowrap;min-height:34px}.task-action button:hover,.mobile-task-heading button:hover{text-decoration:underline}.compact-batches,.mobile-tasks{display:none}.tasks-empty{padding:57px 24px 67px;text-align:center}.empty-icon{margin:0 auto 15px;width:45px;height:45px;display:grid;place-items:center;background:#f0f4f9;color:#7a91ad;border:1px solid #e2e9f2;border-radius:8px}.tasks-empty h3{font-size:14px;font-weight:550;line-height:1.6;margin:0 0 8px}.tasks-empty p{font-size:14px;line-height:1.8;margin:0;color:var(--muted)}.task-pagination{display:flex;align-items:center;justify-content:space-between;gap:12px;padding:14px 24px;border-top:1px solid var(--line);font-size:12px;color:var(--muted)}.task-pagination button{font-size:14px;display:flex;gap:6px;align-items:center;min-height:36px;white-space:nowrap}
